DECLARE
    V_P_CNT	NUMBER(3);
    V_A_CNT	NUMBER(3);
    V_PK	VARCHAR2(20);
    V_AK	VARCHAR2(20);
BEGIN

    V_P_CNT := 0; 
    V_A_CNT := 0; 
    
    FOR ACTION IN (
        SELECT *
        FROM MWIPFATDEF_OLD
    )
    LOOP
        BEGIN
            SELECT POINT_KEY 
            INTO V_PK 
            FROM MWIPFATDEF
            WHERE FACTORY = ACTION.FACTORY
                AND MAT_ID = ACTION.MAT_ID
                AND MAT_VER = ACTION.MAT_VER
                AND FLOW = ACTION.FLOW
                AND OPER = ACTION.OPER
                AND OPT_LEVEL = ACTION.OPT_LEVEL;
            
            EXCEPTION
               WHEN NO_DATA_FOUND THEN  -- catches all 'no data found' errors
                   V_A_CNT := 0; 
                   
                   V_P_CNT := V_P_CNT + 1;
                   V_PK := ACTION.CREATE_TIME||TRIM(TO_CHAR(V_P_CNT, '000'));
                   
        END;
             
        V_A_CNT := V_A_CNT + 1;
        V_AK := V_PK||TRIM(TO_CHAR(V_A_CNT, '000'));
                
        IF ACTION.TRAN_CODE = 'HOLD' THEN
            ACTION.LOT_CODE, ACTION.HOLD_PASSWORD, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
            ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
            ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
            ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
        END IF;
        
        IF ACTION.TRAN_CODE = 'SKIP' THEN
            IF SUBSTR(ACTION.COND1_FIELD_VALUE_3, 1, 5) = 'TFCNT' THEN
            
                TRIM(SUBSTR(ACTION.COND1_FIELD_VALUE_3, 7, 10)), ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                TRIM(SUBSTR(ACTION.COND1_FIELD_VALUE_3, 18, 10)), ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
                ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
                ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
            
            ELSIF SUBSTR(ACTION.COND1_FIELD_VALUE_3, 1, 5) = 'TFOPR' THEN
            
                ' ', ' ', TRIM(SUBSTR(ACTION.COND1_FIELD_VALUE_3, 7, 10)), ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                ' ', ' ', TRIM(SUBSTR(ACTION.COND1_FIELD_VALUE_3, 18, 10)), ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
                ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
                ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
            
            ELSE
            
                ACTION.TO_FLOW, ACTION.TO_FLOW_SEQ_NUM, ACTION.TO_OPER, ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
                ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
                ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
                ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
            
            END IF;
        END IF;
        
        IF ACTION.TRAN_CODE = 'MOVE' THEN
            ACTION.TO_FLOW, ACTION.TO_FLOW_SEQ_NUM, ACTION.TO_OPER, ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
            ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
            ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
            ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
            ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
        END IF;
        
        IF ACTION.TRAN_CODE = 'TERMINATE' THEN
            ACTION.LOT_CODE, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 
            ACTION.CMF_1, ACTION.CMF_2, ACTION.CMF_3, ACTION.CMF_4, ACTION.CMF_5, ACTION.CMF_6, ACTION.CMF_7, ACTION.CMF_8, ACTION.CMF_9, ACTION.CMF_10, 
            ACTION.CMF_11, ACTION.CMF_12, ACTION.CMF_13, ACTION.CMF_14, ACTION.CMF_15, ACTION.CMF_16, ACTION.CMF_17, ACTION.CMF_18, ACTION.CMF_19, ACTION.CMF_20, 
            ACTION.LOT_COMMENT, ACTION.CREATE_USER_ID, ACTION.CREATE_TIME, ACTION.UPDATE_USER_ID, ACTION.UPDATE_TIME);
        END IF;
        
        
        IF TRIM(ACTION.LOT_TYPE) IS NOT NULL THEN
        END IF;
        
        IF TRIM(ACTION.LOT_ID) IS NOT NULL THEN
        END IF;
        
        IF TRIM(ACTION.COND1_FIELD_NAME) IS NOT NULL THEN
        
            IF SUBSTR(ACTION.COND1_FIELD_NAME, 1, 7) = 'LOTSTAT' THEN
            END IF;
            
            IF SUBSTR(ACTION.COND1_FIELD_NAME, 1, 7) = 'LOTATTR' THEN
            END IF;
        
        END IF;
        
        IF TRIM(ACTION.COND2_FIELD_NAME) IS NOT NULL THEN
        
            IF SUBSTR(ACTION.COND2_FIELD_NAME, 1, 7) = 'LOTSTAT' THEN
            END IF;
            
            IF SUBSTR(ACTION.COND1_FIELD_NAME, 1, 7) = 'LOTATTR' THEN
            END IF;
        
        END IF;
        
        IF TRIM(ACTION.COND3_FIELD_NAME) IS NOT NULL THEN
        
            IF SUBSTR(ACTION.COND3_FIELD_NAME, 1, 7) = 'LOTSTAT' THEN
            END IF;
            
            IF SUBSTR(ACTION.COND1_FIELD_NAME, 1, 7) = 'LOTATTR' THEN
            END IF;
        
        END IF;
    
    END LOOP;
END;
/

BEGIN

    FOR COND IN (
         SELECT * FROM (
             SELECT ACTION_KEY, MIN(SEQ_NO) AS SEQ_NO, COUNT(*) AS COUNT 
             FROM MWIPFATCND 
             GROUP BY ACTION_KEY
         ) WHERE COUNT > 1
    )
    LOOP

        UPDATE MWIPFATCND SET AND_OR = 'AND' WHERE ACTION_KEY = COND.ACTION_KEY AND SEQ_NO > COND.SEQ_NO;                 

        UPDATE MWIPFATCND SET SEQ_NO = 1 WHERE ACTION_KEY = COND.ACTION_KEY AND SEQ_NO = COND.SEQ_NO;                 
    
    END LOOP;
END;
/

UPDATE MWIPFATCND SET SEQ_NO = 1 WHERE ACTION_KEY IN (
    SELECT ACTION_KEY FROM (
        SELECT ACTION_KEY, MIN(SEQ_NO) AS SEQ_NO, COUNT(*) AS COUNT 
        FROM MWIPFATCND 
        GROUP BY ACTION_KEY
    ) WHERE COUNT = 1
);

DECLARE
    V_SEQ NUMBER(3);
    V_AK  VARCHAR(20);
BEGIN

    V_SEQ := 0;
    V_AK := ' ';

    FOR COND IN (
        SELECT * 
        FROM MWIPFATCND 
        WHERE ACTION_KEY IN (
            SELECT ACTION_KEY 
            FROM (
                SELECT ACTION_KEY, COUNT(*) AS COUNT 
                FROM MWIPFATCND 
                GROUP BY ACTION_KEY
            ) WHERE COUNT > 1
        )
    )
    LOOP
    
        IF COND.ACTION_KEY != V_AK AND COND.SEQ_NO = 1 THEN
            V_AK := COND.ACTION_KEY;
            V_SEQ := 2; 
        END IF; 
        
        IF COND.ACTION_KEY = V_AK AND COND.SEQ_NO > 1 THEN
            
            UPDATE MWIPFATCND SET SEQ_NO = V_SEQ WHERE ACTION_KEY = COND.ACTION_KEY AND SEQ_NO = COND.SEQ_NO;
            V_SEQ := V_SEQ + 1;                 

        END IF;
    
    END LOOP;
END;
/





