    TRAN_TIME,
    CRR_ID
) TABLESPACE HISTORY_IDX_TS;


SELECT
    CRR_ID                    ,
    HIST_SEQ                  ,
    TRAN_TIME                 ,
    SYS_TRAN_TIME             ,
    TRAN_CODE                 ,
    FACTORY                   ,
    CRR_STATUS                ,
    CRR_STATUS_FLAG           ,
    USAGE_COUNT               ,
    CLEAN_COUNT               ,
    RES_ID                    ,
    SUBRES_ID                 ,
    PORT_ID                   ,
    LOCATION_1                ,
    LOCATION_2                ,
    LOCATION_3                ,
    LOCATION_4                ,
    LOCATION_5                ,
    DECODE(CRR_STATUS_FLAG, 'N', 'Y', ' '),
    FINISH_CLEAN_FLAG         ,
    LAST_CLEAN_TIME           ,
    LOT_ID                    ,
    LOT_HIST_SEQ              ,
    QTY_1                     ,
    QTY_2                     ,
    QTY_3                     ,
    TBL_SLOT                  ,
    MOVE_FLAG                 ,
    EMPTY_FLAG                ,
    STOCK_IN_TIME             ,
    TRAN_CMF_1                ,
    TRAN_CMF_2                ,
    TRAN_CMF_3                ,
    TRAN_CMF_4                ,
    TRAN_CMF_5                ,
    TRAN_CMF_6                ,
    TRAN_CMF_7                ,
    TRAN_CMF_8                ,
    TRAN_CMF_9                ,
    TRAN_CMF_10               ,
    TRAN_CMF_11               ,
    TRAN_CMF_12               ,
    TRAN_CMF_13               ,
    TRAN_CMF_14               ,
    TRAN_CMF_15               ,
    TRAN_CMF_16               ,
    TRAN_CMF_17               ,
    TRAN_CMF_18               ,
    TRAN_CMF_19               ,
    TRAN_CMF_20               ,
    TRAN_USER_ID              ,
    TRAN_COMMENT
FROM MRASCRRHIS_OLD
);







Delete from MSVMSVCMBR where SERVICE_NAME = 'RAS_View_Carrier';


Delete from MSVMSVCMBR where SERVICE_NAME = 'RAS_View_Carrier_History_List';


Delete from MSVMSVCMBR where SERVICE_NAME = 'RAS_View_Carrier_History_List_By_Lot';

Delete from MSVMSVCMBR where SERVICE_NAME = 'RAS_View_Carrier_Lot_List_Detail';


Delete from MSVMSVCMBR where SERVICE_NAME = 'WIP_Start_Batch';



BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
		WHERE TABLE_NAME = 'GLOBAL_OPTION'
		AND KEY_1 = 'IsCheckCarrierUsageLimit'
		) 
	LOOP

	END LOOP;
END ;
